class Animal {
    protected String name;

    public Animal(String name) {
        this.name = name;
    }

    public String makeSound() {
        return name + " makes a generic sound";
    }
}

class Dog extends Animal {
    public Dog(String name) {
        super(name); // gọi constructor của Animal
    }

    @Override
    public String makeSound() {
        return name + " barks"; // truy cập field kế thừa từ Animal
    }
}

class Base {
    protected int level = 1;
}

class Advanced extends Base {
    protected int level = 2; // che field 'level' của Base

    public void printLevels() {
        System.out.println("this.level = " + this.level);   // 2
        System.out.println("super.level = " + super.level); // 1
    }
}

class Shape {
    public double area() {
        return 0;
    }

    // method overloading: cung ten describe, khac danh sach tham so
    public String describe() {
        return "Shape with area " + area();
    }

    public String describe(String prefix) {
        return prefix + ": " + describe();
    }
}

class Circle extends Shape {
    private final double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    @Override // method overriding: cùng chữ ký với Shape.area()
    public double area() {
        return Math.PI * radius * radius;
    }
}

class PolymorphismDemo {
    public static void main(String[] args) {
        Shape shape = new Circle(2.0); // bien khai bao kieu Shape
        System.out.println(shape.describe()); // goi Circle.area() luc runtime
    }
}

class Animal {
    String speak() { return "..."; }
    static String kind() { return "Animal"; }
}

class Dog extends Animal {
    @Override String speak() { return "Woof"; }   // override: dynamic dispatch
    static String kind() { return "Dog"; }        // HIDING, khong phai override
    String fetch() { return "ball"; }             // chi co o Dog
}

class DispatchDemo {
    public static void main(String[] args) {
        Animal a = new Dog();            // upcast: an toan, tu dong

        System.out.println(a.speak());   // "Woof"  -> theo runtime type
        // a.fetch();                    // LOI COMPILE -> theo compile-time type

        // static method KHONG polymorphic: phan giai theo compile-time type
        System.out.println(((Animal) new Dog()).kind()); // "Animal"
    }
}

class Shape {
    public double area() {
        return 0;
    }
}

class Circle extends Shape {
    private final double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }
}

class DowncastDemo {
    public static void main(String[] args) {
        Shape shape = new Circle(1.5);

        if (shape instanceof Circle circle) { // downcast an toan
            System.out.println("radius-based area: " + circle.area());
        } else {
            System.out.println("Khong phai Circle, bo qua downcast");
        }
    }
}

abstract class Shape { abstract double area(); }
class Circle extends Shape {
    double r = 2;
    double area() { return Math.PI * r * r; }
    double circumference() { return 2 * Math.PI * r; }
}
class Square extends Shape {
    double side = 3;
    double area() { return side * side; }
}

class CastDemo {
    static String describe(Shape s) {
        // Java 16+: pattern matching for instanceof -> kiem tra + bind mot buoc
        if (s instanceof Circle c) {
            return "circle, chu vi = " + c.circumference();
        }
        return "shape, dien tich = " + s.area();
    }

    public static void main(String[] args) {
        System.out.println(describe(new Circle()));
        System.out.println(describe(new Square()));

        Shape s = new Square();
        try {
            Circle bad = (Circle) s;   // compile OK, runtime FAIL
            System.out.println(bad.area());
        } catch (ClassCastException e) {
            System.out.println("ClassCastException: " + e.getMessage());
        }
    }
}

