interface DiscountPolicy {
    long apply(long amount);
}

class NoDiscount implements DiscountPolicy {
    public long apply(long amount) { return amount; }
}

class PercentDiscount implements DiscountPolicy {
    private final int percent;
    PercentDiscount(int percent) { this.percent = percent; }
    public long apply(long amount) { return amount - amount * percent / 100; }
}

// Chi phu thuoc vao hop dong, khong biet implementation nao dang chay
class Checkout {
    private final DiscountPolicy policy;   // constructor injection
    Checkout(DiscountPolicy policy) { this.policy = policy; }
    long total(long amount) { return policy.apply(amount); }
}

class StrategyDemo {
    public static void main(String[] args) {
        System.out.println(new Checkout(new NoDiscount()).total(1000));        // 1000
        System.out.println(new Checkout(new PercentDiscount(10)).total(1000)); // 900
    }
}

